 * 
 * @param {Object} props
 * @param {string} props.variant - Either 'full' or 'centered'
 * @param {React.ReactNode} props.children - The content to be rendered inside the layout
 */
const Layout = ({ variant = 'centered', children }) => {
  // Determine the base classes based on the variant
  const baseClasses = 'bg-white rounded-lg shadow-sm p-6'; // Optional: Added some basic styling for visibility

  let layoutClasses = '';

  if (variant === 'full') {
    layoutClasses = 'w-full';
  } else {
    // Default to 'centered' if an invalid variant is passed
    layoutClasses = 'max-w-[1000px] mx-auto';
  }

  return (
    <div className={`${baseClasses} ${layoutClasses}`}>
      {children}
    </div>
  );
};

export default Layout;
