                <td>Chicago</td>
            </tr>
        </tbody>
    </table>

    <script>
        const table = document.getElementById('sortableTable');
        const headers = table.querySelectorAll('th');
        const rows = table.querySelectorAll('tbody tr');

        headers.forEach(header => {
            header.addEventListener('click', () => {
                const column = header.getAttribute('data-column');
                const isAscending = !header.classList.contains('asc');
                header.classList.remove('asc', 'desc');
                header.classList.add(isAscending ? 'asc' : 'desc');

                rows.forEach(row => {
                    const cell = row.children[column];
                    const value = cell.textContent.trim();
                    const type = isNaN(value) ? 'string' : 'number';

                    if (type === 'number') {
                        row.style.display = isAscending ? 'none' : 'table-row';
                    } else {
                        const comparison = value.localeCompare(header.textContent.trim());
                        row.style.display = isAscending ? (comparison >= 0 ? 'none' : 'table-row') : (comparison <= 0 ? 'none' : 'table-row');
                    }
                });
            });
        });
    </script>
</body>
</html>
