    // A simple enum to represent choices
    public enum Choice {
        ATTACK, FLEE, TALK
    }

    public void showDialogue(String characterName, String message, Choice[] options) {
        System.out.println("--- " + characterName + " ---");
        System.out.println(message);
        System.out.println();

        for (Choice option : options) {
            System.out.println("[" + option + "]");
        }
        System.out.println();

        // Get user input
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine().toUpperCase();

        // Process input
        switch (input) {
            case "ATTACK":
                handleAction(Choice.ATTACK);
                break;
            case "FLEE":
                handleAction(Choice.FLEE);
                break;
            case "TALK":
                handleAction(Choice.TALK);
                break;
            default:
                System.out.println("Invalid choice. Please try again.");
                // Optional: Call showDialogue again to retry
                break;
        }
    }

    private void handleAction(Choice choice) {
        System.out.println("You chose: " + choice);
        // Game logic goes here
    }
}
```

---

